"use strict";
const fs = require("node:fs");
const path = require("node:path");
const cp = require("node:child_process");
const crypto = require("node:crypto");
const root = __dirname;
const progress = JSON.parse(fs.readFileSync(path.join(root, "progress.json")));
if (progress.count !== 42) throw new Error("Wait for measured trials to finish");
const hash = (bytes) => crypto.createHash("sha256").update(bytes).digest("hex");
const gitSource = (ref) => cp.execFileSync("git", ["show", `${ref}:more_itertools/more.py`], { cwd: path.join(root, "repos/more-itertools"), encoding: "utf8" });
const versions = [
  { version: "parent", source: gitSource("2fe1b2eeb9d75f994113fe3ac76d14b6bcd6fb10") },
  { version: "upstream_reference", source: gitSource("dc2664b4a7c66209485c9f5e359137bf4b365eb3") },
  ...progress.completed.filter((r) => r.task === "more-itertools-1247").map((r) => ({ version: `${r.cell}-r${r.repetition}`, cell: r.cell, run: r.repetition,
    source: fs.readFileSync(path.join(root, "trials", `${r.task}--${r.cell}--r${r.repetition}`, "runs", r.task, `${r.cell}-r${r.repetition}`, "more_itertools/more.py"), "utf8") })),
];
const program = `import json, sys
data = json.load(sys.stdin)
sys.path.insert(0, data["support"])
namespace = {"__name__": "more_itertools.more", "__package__": "more_itertools", "__file__": "<frozen-source>"}
exec(compile(data["source"], "<frozen-source>", "exec"), namespace)
cls = namespace["numeric_range"]
if data["operation"] == "large_length":
    r = cls(1e16, 1e16 + 4, 1e-12)
    n = len(r)
    correct = n > 0 and 1e16 + (n - 1) * 1e-12 < 1e16 + 4 <= 1e16 + n * 1e-12
    print(json.dumps({"passed": correct, "length": n, "boundary_matches_iteration_formula": correct}))
else:
    r = cls(1e16, 1e16 + 4, 0.1)
    items = list(iter(r))
    expected = items.index(1e16 + 2)
    actual = r.index(1e16 + 2)
    print(json.dumps({"passed": actual == expected, "index": actual, "expected_first_index": expected, "bounded_iteration_count": len(items)}))
`;
const results = versions.map(({ source, ...meta }) => {
  const cases = ["large_length", "first_repeated_index"].map((operation) => {
    const start = Date.now();
    const result = cp.spawnSync(path.join(root, "venvs/more-itertools/bin/python"), ["-B", "-c", program], {
      input: JSON.stringify({ source, operation, support: path.join(root, "validation/more-itertools-1247/checkout") }),
      encoding: "utf8", timeout: 2000, env: { ...process.env, PYTHONDONTWRITEBYTECODE: "1" },
    });
    const timedOut = result.error?.code === "ETIMEDOUT";
    let value;
    try { value = JSON.parse(result.stdout); } catch { value = { passed: false, exception_tail: result.stderr?.slice(-1000) }; }
    return { operation, ...value, passed: !timedOut && result.status === 0 && value.passed === true,
      timed_out: timedOut, exit: result.status, duration_ms: Date.now() - start };
  });
  return { ...meta, source_sha256: hash(source), cases };
});
const report = { kind: "Post-hoc uniform large-input and sequence-contract checks; original eight predeclared queries unchanged",
  amendment: JSON.parse(fs.readFileSync(path.join(root, "protocol/cost-amendment.json"))), timeout_ms_per_case: 2000,
  methodology: "Same two checks for parent, upstream reference and all six numeric_range artifacts after all measured trials; frozen source evaluated in a new child process, no measured checkout changes or model reruns",
  python_program: program, controller_source: fs.readFileSync(__filename, "utf8"), results };
fs.writeFileSync(path.join(root, "cost-probes.json"), JSON.stringify(report, null, 2));
console.log(JSON.stringify(results.map((r) => ({ version: r.version, cases: r.cases.map((c) => ({ operation: c.operation, passed: c.passed, timeout: c.timed_out, actual: c.index ?? c.length, expected: c.expected_first_index })) }))));
